input.command:
sed -n 618,626p v3/types.ts; grep -n "_emojiRegex" v3/types.ts; mkdir -p /tmp/chk && cat > /tmp/chk/c.test.ts <<'EOF'
import { check } from "recheck";
import { test, expect } from "vitest";
import * as r from "/work/packages/zod/src/v4/core/regexes.js";
test("safe", async () => {
  const pats: RegExp[] = [];
  for (const [k, v] of Object.entries(r)) if (v instanceof RegExp) pats.push(v);
  pats.push(r.emoji(), r.mac(), r.mac("-"), r.uuid());
  for (let i = 1; i <= 8; i++) pats.push(r.uuid(i));
  pats.push(r.string(), r.string({ minimum: 1, maximum: 5 }));
  for (const p of [null, -1, 0, 3, 6] as any[]) {
    pats.push(r.time({ precision: p }));
    for (const local of [true, false]) for (const offset of [true, false]) pats.push(r.datetime({ precision: p, local, offset }));
  }
  const bad: string[] = [];
  for (const p of pats) { const x = await check(p.source, p.flags); if (x.status !== "safe") bad.push(p.source.slice(0,80)+" "+p.flags+" "+x.status); }
  expect(bad).toEqual([]);
}, 600000);
EOF
cp /tmp/chk/c.test.ts v4/classic/tests/zz-tmp.test.ts && cd /work && pnpm vitest run packages/zod/src/v4/classic/tests/zz-tmp.test.ts 2>&1 | tail -30

